import zipfile
import xml.etree.ElementTree as ET
import re
import sys

NS = {
    'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'rel': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'pkgrel': 'http://schemas.openxmlformats.org/package/2006/relationships',
}

def q(tag):
    return '{' + NS['main'] + '}' + tag

def get_cell_value(cell, shared_strings):
    t = cell.get('t')
    v = cell.find(q('v'))
    text = v.text if v is not None else ''
    if t == 's':
        return shared_strings[int(text)]
    if t == 'str' or t == 'e':
        return text
    if t == 'b':
        return text == '1'
    if t == 'inlineStr':
        is_el = cell.find(q('is'))
        if is_el is not None:
            return ''.join(x.text or '' for x in is_el.iter(q('t')))
    return text

def col_letter(ref):
    return re.match(r'[A-Z]+', ref).group(0)

def col_index(letter):
    idx = 0
    for ch in letter:
        idx = idx * 26 + (ord(ch) - 64)
    return idx

def main(path):
    with zipfile.ZipFile(path) as z:
        names = z.namelist()
        # Shared strings
        shared = []
        if 'xl/sharedStrings.xml' in names:
            root = ET.fromstring(z.read('xl/sharedStrings.xml'))
            for si in root.findall(q('si')):
                shared.append(''.join(t.text or '' for t in si.iter(q('t'))))
        # Workbook sheet list
        wb_root = ET.fromstring(z.read('xl/workbook.xml'))
        sheets = [(s.get('name'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'))
                  for s in wb_root.find(q('sheets'))]
        # Map rId to sheet target via workbook rels
        rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
        rel_map = {}
        for rel in rels_root:
            rel_map[rel.get('Id')] = rel.get('Target')
        for name, rid in sheets:
            target = rel_map[rid]
            if not target.startswith('xl/'):
                target = 'xl/' + target.lstrip('/')
            sheet_path = target
            print(f"\n=== Sheet: {name} ===")
            sroot = ET.fromstring(z.read(sheet_path))
            sheet_data = sroot.find(q('sheetData'))
            if sheet_data is None:
                print("(empty)")
                continue
            max_col = 0
            rows = []
            for row in sheet_data.findall(q('row')):
                cells = {}
                for cell in row.findall(q('c')):
                    ref = cell.get('r')
                    if ref is None:
                        continue
                    ci = col_index(col_letter(ref))
                    cells[ci] = get_cell_value(cell, shared)
                    max_col = max(max_col, ci)
                rows.append((int(row.get('r')), cells))
            for rnum, cells in rows:
                line = []
                for c in range(1, max_col + 1):
                    val = cells.get(c, '')
                    line.append('' if val == '' else str(val))
                print(f"R{rnum}: " + ' | '.join(line))

